run:
set -e
mkdir -p src/payments
cat > src/payments/retry.ts <<'TS'
import { sendCharge, type ChargeRequest } from "./charge";

/** One key per order, so the provider drops a repeated charge. */
export function idempotencyKey(orderId: string): string {
  return `order_${orderId}_charge`;
}

export async function chargeWithRetry(req: ChargeRequest) {
  const key = idempotencyKey(req.orderId);
  return sendCharge({ ...req, idempotencyKey: key });
}
TS
cat > src/payments/charge.ts <<'TS'
export interface ChargeRequest {
  readonly orderId: string;
  readonly amount: number;
  readonly idempotencyKey?: string;
}

export async function sendCharge(req: ChargeRequest) {
  return { id: `ch_${req.orderId}`, amount: req.amount };
}
TS
